mapper.select:
SELECT * FROM ( SELECT ROW_NUMBER() OVER (ORDER BY "conSeq" DESC) AS RNUM, TB.* FROM ( SELECT A.CON_SEQ AS "conSeq", B.CODE_NM AS "codeNm", A.CON_NM AS "conNm", A.CON_TIMEINTERVAL AS "conTimeInterval", FN_DETAILCODENM(A.CON_PLAYTYPE) AS "conPlayType", CASE WHEN (A.CON_NEXTCONSEQ) > 0 THEN ( SELECT CON_NM FROM TB_CONTENT C WHERE C.CON_SEQ = A.CON_NEXTCONSEQ ) ELSE '컨텐츠 없음' END AS "conNextConSeq" FROM TB_CONTENT A JOIN LETTCCMMNDETAILCODE B ON A.CON_TYPE = B.CODE WHERE 1=1
AND A.CON_NM LIKE CONCAT('%', #{searchKeyword}, '%')
AND CAST(A.CON_SEQ AS VARCHAR) LIKE CONCAT('%', #{searchKeyword}, '%')
AND A.CON_TYPE = #{conType}
) TB ) TA WHERE TA.RNUM BETWEEN #{firstIndex} + 1 AND #{firstIndex} + #{recordCountPerPage}

mapper.update:
UPDATE TB_CONTENT SET CON_TYPE = #{conType}, CON_NM = #{conNm}, CON_PLAYTYPE = #{conPlayType}, CON_TIMEINTERVAL = #{conTimeInterval},
CON_THUMBNAIL = #{conThumbnail,jdbcType=VARCHAR},
CON_USEYN = #{conUseYn}, CON_WIDTH = #{conWidth}, CON_HEIGHT = #{conHeight}, CON_NEXTCONSEQ = #{conNextConSeq,jdbcType=VARCHAR}, LAST_UPDT_PNTTM = NOW(), LAST_UPDUSR_ID = #{frstRegisterId,jdbcType=VARCHAR}, CON_TEXT = #{conText}
, CON_FILE = #{conFile}
WHERE CON_SEQ = #{conSeq}
